// Generated by datlechin/flarum-pwa. The cache key is interpolated by the
// PHP controller; bumping it drops every previously cached entry on next
// activation.

const CACHE = 'flarum-pwa-{{VERSION}}';

self.addEventListener('install', (event) => {
  // Take over as soon as we're installed; otherwise the user has to close
  // every tab to pick up an updated worker.
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((k) => k.startsWith('flarum-pwa-') && k !== CACHE)
          .map((k) => caches.delete(k))
      );
      await self.clients.claim();
    })()
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;

  if (req.method !== 'GET') return;

  const url = new URL(req.url);

  // Only handle requests on our own origin. Cross-origin assets (CDNs,
  // avatar hosts) go through the network normally.
  if (url.origin !== self.location.origin) return;

  // The API is dynamic by definition. Don't cache it.
  if (url.pathname.includes('/api/')) return;

  // Same-origin static-ish GETs: stale-while-revalidate. Serve from cache
  // immediately if we have it; refresh the cache in the background so the
  // next visit gets the new version.
  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const cached = await cache.match(req);
      const networkPromise = fetch(req)
        .then((res) => {
          if (res.ok && res.type === 'basic') {
            cache.put(req, res.clone());
          }
          return res;
        })
        .catch(() => cached); // offline: fall back to whatever we have

      return cached || networkPromise;
    })
  );
});
